async(page)=>{const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:4173/');await page.evaluate(()=>localStorage.setItem('machine-primary-assets-v1',JSON.stringify({state:{intro:true},version:0})));await page.reload();await page.getByRole('button',{name:'Pan map gesture',exact:true}).waitFor();await page.waitForTimeout(1500);const box=()=>page.getByRole('button',{name:'Track TOFFEE',exact:true}).boundingBox();const moved=async(before)=>{await page.waitForTimeout(600);const after=await box();if(!before||!after||Math.hypot(after.x-before.x,after.y-before.y)<2)throw Error('Camera did not move');};for(const name of ['Pan left','Rotate right','Zoom in']){const before=await box();await page.getByRole('button',{name,exact:true}).click();await moved(before);}await page.getByRole('button',{name:'Reset map view',exact:true}).click();await page.waitForTimeout(600);let before=await box();await page.mouse.move(650,700);await page.mouse.down();await page.mouse.move(750,730,{steps:12});await page.mouse.up();await moved(before);await page.getByRole('button',{name:'Rotate map gesture',exact:true}).click();before=await box();await page.mouse.move(650,700);await page.mouse.down();await page.mouse.move(750,730,{steps:12});await page.mouse.up();await moved(before);await page.getByRole('button',{name:'Map gesture help'}).click();await page.getByText('Touch: one finger to rotate.',{exact:false}).waitFor();await page.screenshot({path:'output/playwright/map-controls-desktop.png'});const context=await page.context().browser().newContext({viewport:{width:430,height:932},isMobile:true,hasTouch:true});const phone=await context.newPage();phone.on('pageerror',e=>errors.push(e.message));await phone.addInitScript(()=>localStorage.setItem('machine-primary-assets-v1',JSON.stringify({state:{intro:true},version:0})));await phone.goto('http://127.0.0.1:4173/');await phone.getByRole('button',{name:'Pan map gesture'}).waitFor();for(const button of await phone.locator('.map-navigation button').all()){const b=await button.boundingBox();if(!b||b.width<44||b.height<36||b.x<0||b.x+b.width>430||b.y+b.height>932)throw Error('Phone control bounds');}await phone.getByRole('button',{name:'Rotate map gesture'}).tap();await phone.getByRole('button',{name:'Zoom in',exact:true}).tap();const cdp=await context.newCDPSession(phone);const touch=(type,points)=>cdp.send('Input.dispatchTouchEvent',{type,touchPoints:points.map(([x,y],id)=>({x,y,id}))});await touch('touchStart',[[160,400]]);await touch('touchMove',[[210,440]]);await touch('touchEnd',[]);await touch('touchStart',[[130,410],[230,410]]);await touch('touchMove',[[100,390],[260,430]]);await touch('touchEnd',[]);await phone.waitForTimeout(1000);await phone.screenshot({path:'output/playwright/map-controls-phone.png'});await context.close();if(errors.length)throw Error(errors.join('\n'));return {mousePan:true,mouseRotate:true,buttons:true,touchGestures:true,errors};}
